from PIL import Image
import numpy as np, math
im = np.array(Image.open('mol_0175.png').convert('L'))
bw = (im < 128).astype(np.uint8)
H,W = bw.shape
# direction count on ring radius r
def ndir(x,y,r=7):
    angs=[]
    for a in range(0,360,5):
        xx=int(round(x+r*math.cos(math.radians(a))))
        yy=int(round(y+r*math.sin(math.radians(a))))
        if 0<=xx<W and 0<=yy<H and bw[yy,xx]:
            angs.append(a)
    # cluster angles
    if not angs: return 0,[]
    clusters=[[angs[0]]]
    for a in angs[1:]:
        if a-clusters[-1][-1]<=10: clusters[-1].append(a)
        else: clusters.append([a])
    if len(clusters)>1 and (clusters[0][0]+360-clusters[-1][-1])<=10:
        clusters[0]=clusters.pop()+clusters[0]
    return len(clusters), [sum(c)/len(c) for c in clusters]
cands=[]
ys,xs = np.nonzero(bw)
for x,y in zip(xs,ys):
    n,angs = ndir(x,y)
    if n>=3:
        cands.append((x,y,n,tuple(round(a) for a in angs)))
# cluster candidate junctions
pts=[]
for x,y,n,angs in cands:
    for p in pts:
        if abs(p[0]-x)<8 and abs(p[1]-y)<8:
            p[2]=max(p[2],n); break
    else:
        pts.append([x,y,n,angs])
for p in sorted(pts, key=lambda t:(t[1],t[0])):
    print(p)
